c-key.pem\" ] && key=\"--public-key $root/.use-cases/trusted-ci-public-key.pem\"\n  \"$use_cases\" validate-ledger --repo \"$root\" $key --json >/dev/null \\\n    || { echo \"pre-commit: use-case ledger invalid \u2014 run: use-cases validate-ledger --repo .\" >&2; exit 1; }\n  # A marker and its binding that disagree is INVALID; stale is fine here.\n  if \"$use_cases\" scan --repo \"$root\" --json 2>/dev/null | grep -Eq '\"status\": *\"INVALID\"'; then\n    echo \"pre-commit: a use-case marker and its binding disagree \u2014 run: use-cases scan --repo .\" >&2\n    exit 1\n  fi\nfi\n"},{"path":"demo-repo/.githooks/pre-push","kind":"file","mode":"755","content":"#!/usr/bin/env bash\n# use-cases: say which bound rows this push touches and where they stand. Advisory only.\nif [ -f \"$(git rev-parse --show-toplevel)/use-cases.yml\" ]; then\n  # The plugin puts use-cases on PATH in Claude sessions; elsewhere set USE_CASES to <plugin>/bin/use-cases.\n  use_cases=\"${USE_CASES:-$(command -v use-cases 2>/dev/null || true)}\"\n  if [ -z \"$use_cases\" ]; then\n    echo \"pre-push: use-cases not found \u2014 install the Use Cases plugin (https://github.com/adammcarter/use-cases) or set USE_CASES=<plugin>/bin/use-cases\" >&2\n    exit 0\n  fi\n  root=\"$(git rev-parse --show-toplevel)\"\n  \"$use_cases\" impact --repo \"$root\" 2>/dev/null || true\n  \"$use_cases\" scan --repo \"$root\" 2>/dev/null | tail -n 20 || true\nfi\nexit 0\n"},{"path":"demo-repo/.gitignore","kind":"file","mode":"644","content":"# use-cases: transient showcase run output (not durable evidence).\nshowcase-runs/\n# use-cases: transient local verification results (the verify -> prove handoff).\n.use-cases/verification-results.jsonl\n"},{"path":"demo-repo/AGENTS.md","kind":"file","mode":"644","content":"# demo-repo\n\n## Use-case driven development\n\nyes \u2014 2026-09-17\n\nThis repo is use-case driven: every functional change starts in `use-cases/`,\nrows are agreed before tests, tests and code are wrapped in the row's markers,\nand `use-cases scan` is the coverage number. The rules live in the Use Cases plugin's\nskills \u2014 `use-case-driven-development` for when and in what order, `use-cases`\nfor the commands \u2014 and every agent working here follows them.\n"},{"path":"demo-repo/bun.lockb","kind":"directory"},{"path":"demo-repo/src","kind":"directory"},{"path":"demo-repo/src/example.ts","kind":"file","mode":"644","content":"// A tiny, self-contained module an adopter might own. The exported\n// function below is the implementation the use-case row\n// `example.feature.happy_path` describes. It is wrapped in a Use Cases\n// marker span (the `@use-case` start/end comments) so the matrix can bind\n// the row to exactly these source lines. Replace it with your own code.\n\n//: @use-case:example.feature.happy_path\nexport function greet(name: string): string {\n  const trimmed = name.trim();\n  if (trimmed === \"\") {\n    throw new Error(\"name must not be empty\");\n  }\n  return `Hello, ${trimmed}!`;\n}\n//: @use-case:end example.feature.happy_path\n"},{"path":"demo-repo/tests","kind":"directory"},{"path":"demo-repo/tests/use-cases","kind":"directory"},{"path":"demo-repo/tests/use-cases/example.feature.happy_path.test.ts","kind":"file","mode":"644","content":"// Acceptance test for the `example.feature.happy_path` use-case row.\n//\n// Run this file directly with\n//   bun x vitest run tests/use-cases/example.feature.happy_path.test.ts\n// or let `use-cases verify` invoke the `js.vitest` preset for the row. Replace\n// these assertions as you replace the example row with your own use case.\nimport { describe, expect, test } from \"vitest\";\nimport { greet } from \"../../src/example.js\";\n\ndescribe(\"example.feature.happy_path\", () => {\n  test(\"greets a named user\", () => {\n    expect(greet(\"Ada\")).toBe(\"Hello, Ada!\");\n  });\n\n  test(\"trims surrounding whitespace\", () => {\n    expect(greet(\"  Ada  \")).toBe(\"Hello, Ada!\");\n  });\n\n  test(\"rejects an empty name\", () => {\n    expect(() => greet(\"   \")).toThrow();\n  });\n});\n"},{"path":"demo-repo/use-cases","kind":"directory"},{"path":"demo-repo/use-cases.yml","kind":"file","mode":"644","content":"schema_version: 1\nworkspace_id: demo-repo\ncomponent_id: demo-repo\ndata_root: .\nuse_cases_dir: use-cases\nevidence_dir: evidence\ndemo_capsules_dir: demo-capsules\nshowcase_runs_dir: showcase-runs\ndefault_workflow_mode: continuous\n# Verifiers map a row's required_verifiers id to a real command. `default` is\n# used by any row that does not name its own verifier. See docs/cli.md.\nverifiers:\n  default: acceptance\n  acceptance:\n    preset: js.vitest\n    evidence_kind: test_result\n"},{"path":"demo-repo/use-cases/example.yml","kind":"file","mode":"644","content":"schema_version: 1\n# A worked example of one use-case row. Copy it for your first real row, then\n# delete this one. One row is one behaviour; its scenarios are its tests \u2014 each\n# scenario below becomes exactly one test, written before the code.\nfeature:\n  id: example.feature\n  name: Example feature\n  summary: A sample use case vended by `use-cases init` \u2014 copy its shape for your own rows.\nmetadata:\n  owner: unassigned\n  lifecycle: active\nuse_cases:\n  - id: example.feature.happy_path\n    title: Example happy path\n    # planned while the row is agreed but unproven; active once tests are green\n    # and both the test and the code are wrapped in this row's markers.\n    lifecycle: active\n    # How much the product depends on this: critical | core | supporting | long_tail.\n    value_tier: core\n    # Where it sits in the user's journey: golden | alternate | edge | negative | failure.\n    journey_role: golden\n    # How often users hit it: common | occasional | rare.\n    usage_frequency: common\n    tags: [example]\n    # Files the behaviour lives in. `use-cases bind` wraps the exact span with a marker.\n    source_refs:\n      - kind: file\n        path: src/example.ts\n    # Who triggers the behaviour: user | agent | script | system.\n    actor: user\n    # What they are trying to achieve, in one sentence.\n    intent: Demonstrate the use-cases row shape so you can copy it.\n    # What must already be true before the trigger.\n    preconditions:\n      - The project is set up.\n    # The event that starts the behaviour.\n    trigger: The user performs the example action.\n    # One golden path, then the bad paths and the edge cases. Each scenario is\n    # one test; a test that proves nothing here is a scenario to write first.\n    scenarios:\n      - id: example.feature.happy_path.golden\n        kind: steps\n        steps:\n          - Perform the example action with valid input.\n          - Observe the expected result.\n      - id: example.feature.happy_path.bad_input\n        kind: steps\n        steps:\n          - Perform the example action with invalid input.\n          - Observe a clear error and no side effect.\n      - id: example.feature.happy_path.edge_empty\n        kind: steps\n        steps:\n          - Perform the example action with empty input.\n          - Observe the documented empty-input behaviour.\n    # What a person can see when the behaviour holds \u2014 the acceptance criteria.\n    observable_outcomes:\n      - The expected result is visible to the user.\n      - Invalid input is refused with a clear message.\n    host_applicability:\n      - host_surface: codex.cli\n        supported: true\n    # Which verifier (from use-cases.yml) has to pass for this row to count.\n    verification_policy:\n      mode: requirements\n      requirements:\n        - evidence_kind: test_result\n          required_verifiers: [acceptance]\n          minimum_count: 1\n    # Whether a human must sign this row off in a showcase before release.\n    approval_policy:\n      mode: none\n"},{"path":"outside","kind":"directory"}],"hooks_path_after":null},{"name":"js_vitest_pnpm_wins_over_npm","setup":{"repository":"demo-repo