 repo is use-case driven: every functional change starts in `use-cases/`,\nrows are agreed before tests, tests and code are wrapped in the row's markers,\nand `use-cases scan` is the coverage number. The rules live in the Use Cases plugin's\nskills \u2014 `use-case-driven-development` for when and in what order, `use-cases`\nfor the commands \u2014 and every agent working here follows them.\n"},{"path":"demo-repo/src","kind":"directory"},{"path":"demo-repo/src/example.ts","kind":"file","mode":"644","content":"// A tiny, self-contained module an adopter might own. The exported\n// function below is the implementation the use-case row\n// `example.feature.happy_path` describes. It is wrapped in a Use Cases\n// marker span (the `@use-case` start/end comments) so the matrix can bind\n// the row to exactly these source lines. Replace it with your own code.\n\n//: @use-case:example.feature.happy_path\nexport function greet(name: string): string {\n  const trimmed = name.trim();\n  if (trimmed === \"\") {\n    throw new Error(\"name must not be empty\");\n  }\n  return `Hello, ${trimmed}!`;\n}\n//: @use-case:end example.feature.happy_path\n"},{"path":"demo-repo/tests","kind":"directory"},{"path":"demo-repo/tests/use-cases","kind":"directory"},{"path":"demo-repo/tests/use-cases/example.feature.happy_path.test.ts","kind":"file","mode":"644","content":"// Acceptance test for the `example.feature.happy_path` use-case row.\n//\n// Run this file directly with\n//   npx vitest run tests/use-cases/example.feature.happy_path.test.ts\n// or let `use-cases verify` invoke the `js.vitest` preset for the row. Replace\n// these assertions as you replace the example row with your own use case.\nimport { describe, expect, test } from \"vitest\";\nimport { greet } from \"../../src/example.js\";\n\ndescribe(\"example.feature.happy_path\", () => {\n  test(\"greets a named user\", () => {\n    expect(greet(\"Ada\")).toBe(\"Hello, Ada!\");\n  });\n\n  test(\"trims surrounding whitespace\", () => {\n    expect(greet(\"  Ada  \")).toBe(\"Hello, Ada!\");\n  });\n\n  test(\"rejects an empty name\", () => {\n    expect(() => greet(\"   \")).toThrow();\n  });\n});\n"},{"path":"demo-repo/use-cases","kind":"directory"},{"path":"demo-repo/use-cases.yml","kind":"file","mode":"644","content":"schema_version: 1\nworkspace_id: demo-repo\ncomponent_id: demo-repo\ndata_root: .\nuse_cases_dir: use-cases\nevidence_dir: evidence\ndemo_capsules_dir: demo-capsules\nshowcase_runs_dir: showcase-runs\ndefault_workflow_mode: continuous\n# Verifiers map a row's required_verifiers id to a real command. `default` is\n# used by any row that does not name its own verifier. See docs/cli.md.\nverifiers:\n  default: acceptance\n  acceptance:\n    preset: js.vitest\n    evidence_kind: test_result\n"},{"path":"demo-repo/use-cases/example.yml","kind":"file","mode":"644","content":"schema_version: 1\n# A worked example of one use-case row. Copy it for your first real row, then\n# delete this one. One row is one behaviour; its scenarios are its tests \u2014 each\n# scenario below becomes exactly one test, written before the code.\nfeature:\n  id: example.feature\n  name: Example feature\n  summary: A sample use case vended by `use-cases init` \u2014 copy its shape for your own rows.\nmetadata:\n  owner: unassigned\n  lifecycle: active\nuse_cases:\n  - id: example.feature.happy_path\n    title: Example happy path\n    # planned while the row is agreed but unproven; active once tests are green\n    # and both the test and the code are wrapped in this row's markers.\n    lifecycle: active\n    # How much the product depends on this: critical | core | supporting | long_tail.\n    value_tier: core\n    # Where it sits in the user's journey: golden | alternate | edge | negative | failure.\n    journey_role: golden\n    # How often users hit it: common | occasional | rare.\n    usage_frequency: common\n    tags: [example]\n    # Files the behaviour lives in. `use-cases bind` wraps the exact span wi