e documented empty-input behaviour.\n    # What a person can see when the behaviour holds \u2014 the acceptance criteria.\n    observable_outcomes:\n      - The expected result is visible to the user.\n      - Invalid input is refused with a clear message.\n    host_applicability:\n      - host_surface: codex.cli\n        supported: true\n    # Which verifier (from use-cases.yml) has to pass for this row to count.\n    verification_policy:\n      mode: requirements\n      requirements:\n        - evidence_kind: test_result\n          required_verifiers: [acceptance]\n          minimum_count: 1\n    # Whether a human must sign this row off in a showcase before release.\n    approval_policy:\n      mode: none\n"},{"path":"outside","kind":"directory"}],"hooks_path_after":null},{"name":"existing_config_directory_blocks","setup":{"repository":"demo-repo","create_repository":true,"git":false,"git_missing":false,"hooks_path":null,"directories":["demo-repo/use-cases.yml"],"files":[],"symlinks":[]},"options":{"today":"2026-09-17"},"outcome":{"result":{"schema_version":1,"status":"blocked","template":"generic","component_id":"demo-repo","default_verifier":{"id":"acceptance","kind":"script","command":["false","TODO-replace-with-your-verifier-command-for-{slug}"]},"created_files":[],"agents_md":null,"git_hooks":null,"next_steps":[],"diagnostics":[{"code":"init.workspace_exists","severity":"error","message":"A workspace config already exists at use-cases.yml. Re-run with --force to overwrite.","source_path":"use-cases.yml","json_pointer":null,"entity_id":null,"related_ids":[]}]}},"tree":[{"path":"demo-repo","kind":"directory"},{"path":"demo-repo/use-cases.yml","kind":"directory"},{"path":"outside","kind":"directory"}],"hooks_path_after":null},{"name":"existing_config_dangling_symlink_is_absent","setup":{"repository":"demo-repo","create_repository":true,"git":false,"git_missing":false,"hooks_path":null,"directories":[],"files":[],"symlinks":[{"path":"demo-repo/use-cases.yml","tar