\n  root=\"$(git rev-parse --show-toplevel)\"\n  \"$use_cases\" impact --repo \"$root\" 2>/dev/null || true\n  \"$use_cases\" scan --repo \"$root\" 2>/dev/null | tail -n 20 || true\nfi\nexit 0\n"},{"path":"demo-repo/use-cases","kind":"directory"},{"path":"demo-repo/use-cases.yml","kind":"file","mode":"644","content":"schema_version: 1\nworkspace_id: demo-repo\ncomponent_id: demo-repo\ndata_root: .\nuse_cases_dir: use-cases\nevidence_dir: evidence\ndemo_capsules_dir: demo-capsules\nshowcase_runs_dir: showcase-runs\ndefault_workflow_mode: continuous\n# Verifiers map a row's required_verifiers id to a real command. `default` is\n# used by any row that does not name its own verifier. See docs/cli.md.\nverifiers:\n  default: acceptance\n  acceptance:\n    # TODO: replace this placeholder with the real command that verifies a row.\n    # `{slug}` is substituted with the row id at run time. It exits non-zero\n    # until you configure it, so a placeholder can never mint a passing proof.\n    kind: script\n    evidence_kind: test_result\n    command: [\"false\", \"TODO-replace-with-your-verifier-command-for-{slug}\"]\n"},{"path":"demo-repo/use-cases/example.yml","kind":"file","mode":"644","content":"schema_version: 1\n# A worked example of one use-case row. Copy it for your first real row, then\n# delete this one. One row is one behaviour; its scenarios are its tests \u2014 each\n# scenario below becomes exactly one test, written before the code.\nfeature:\n  id: example.feature\n  name: Example feature\n  summary: A sample use case vended by `use-cases init` \u2014 copy its shape for your own rows.\nmetadata:\n  owner: unassigned\n  lifecycle: active\nuse_cases:\n  - id: example.feature.happy_path\n    title: Example happy path\n    # planned while the row is agreed but unproven; active once tests are green\n    # and both the test and the code are wrapped in this row's markers.\n    lifecycle: active\n    # How much the product depends on this: critical | core | supporting | long_tail.\n    value_tier: core\n    # Where it sits in the user's journey: golden | alternate | edge | negative | failure.\n    journey_role: golden\n    # How often users hit it: common | occasional | rare.\n    usage_frequency: common\n    tags: [example]\n    # Files the behaviour lives in. `use-cases bind` wraps the exact span with a marker.\n    source_refs:\n      - kind: file\n        path: src/example.ts\n    # Who triggers the behaviour: user | agent | script | system.\n    actor: user\n    # What they are trying to achieve, in one sentence.\n    intent: Demonstrate the use-cases row shape so you can copy it.\n    # What must already be true before the trigger.\n    preconditions:\n      - The project is set up.\n    # The event that starts the behaviour.\n    trigger: The user performs the example action.\n    # One golden path, then the bad paths and the edge cases. Each scenario is\n    # one test; a test that proves nothing here is a scenario to write first.\n    scenarios:\n      - id: example.feature.happy_path.golden\n        kind: steps\n        steps:\n          - Perform the example action with valid input.\n          - Observe the expected result.\n      - id: example.feature.happy_path.bad_input\n        kind: steps\n        steps:\n          - Perform the example action with invalid input.\n          - Observe a clear error and no side effect.\n      - id: example.feature.happy_path.edge_empty\n        kind: steps\n        steps:\n          - Perform the example action with empty input.\n          - Observe the documented empty-input behaviour.\n    # What a person can see when the behaviour holds \u2014 the acceptance criteria.\n    observable_outcomes:\n      - The expected result is visible to the user.\n      - Invalid input is refused with a clear message.\n    host_applicability:\n      - host_surface: codex.cli\n        supported: true\n    # Which verifier (from use-cases.yml) has to pass for this row to count.\n    verification_policy:\n      mode: requirements\n      requirements:\n        - evidence_kind: test_result\n          required_verifiers: [acceptance]\n          minimum_count: 1\n    # Whether a human must sign this row off in a showcase before release.\n    approval_policy:\n      mode: none\n"},{"path":"outside","kind":"directory"}],"hooks_path_after":"  my hooks  \n"},{"name":"hook_already_carrying_the_block_is_left_alone","setup":{"repository":"demo-repo","create_repository":true,"git":false,"git_missing":false,"hooks_path":null,"directories":[],"files":[{"path":"demo-repo/.githooks/pre-commit","content":"#!/bin/sh\n# use-cases: mine\n","mode":384},{"path":"demo-repo/.githooks/pre-push","content":"#!/bin/sh\necho push\n","mode":384}],"symlinks":[]},"options":{"today":"2026-09-17"},"outcome":{"result":{"schema_version":1,"status":"created","template":"generic","component_id":"demo-repo","default_verifier":{"id":"acceptance","kind":"script","command":["false","TODO-replace-with-your-verifier-command-for-{slug}"]},"created_files":["use-cases.yml","use-cases/example.yml",".gitignore","AGENTS.md"],"agents_md":{"status":"created","decision":"yes"},"git_hooks":{"hooks_dir":".githooks","hooks_path_set":false,"extended":[".githooks/pre-push"]},"next_steps":["Point git at the hooks once the repo is initialised: `git config core.hooksPath .githooks`.","Copy use-cases/example.yml's row for your first real use case, then delete the example.","Run `use-cases matrix validate --repo . --json` to confirm the matrix is clean.","Bind the implementing code with `use-cases bind` \u2014 code-marker grammar in docs/markers-adoption.md.","Wire the `acceptance` verifier in use-cases.yml to your real test command (docs/cli.md).","Generate an ed25519 keypair \u2014 commit the PUBLIC key, keep the PRIVATE key in a CI secret only (docs/security.md).","Let trusted CI mint FRESH proofs with `use-cases prove` (docs/cli.md, docs/security.md)."],"diagnostics":[]}},"tree":[{"path":"demo-repo","kind":"directory